        JDOMNodePointer attrPtr = new JDOMNodePointer(rootPtr, attr);

        Element child = new Element("child");
        JDOMNodePointer childPtr = new JDOMNodePointer(rootPtr, child);

        int resAttrFirst = rootPtr.compareChildNodePointers(attrPtr, childPtr);
        int resAttrAfter = rootPtr.compareChildNodePointers(childPtr, attrPtr);

        assertTrue(resAttrFirst < 0, "Attribute should come before child");
        assertTrue(resAttrAfter > 0, "Child should come after attribute");
    }

