            final NamedNodeMap map = ((Node) getNode()).getAttributes();
            final int length = map.getLength();
            for (int i = 0; i < length; i++) {
                final Node n = map.item(i);
                if (n == node1) {
                    return -1;
                }
                if (n == node2) {
                    return 1;
                }
            }
            return 0; // Should not happen
