package org.apache.commons.jxpath.xml;

import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;

import static org.junit.jupiter.api.Assertions.*;

public class ParseXMLTests {

    @Test
    void testParseXMLReturnsDocument() throws Exception {
        String xml = "<root><child>value</child></root>";
        InputStream in = new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8));
        JDOMParser parser = new JDOMParser();
        Object result = parser.parseXML(in);

        assertNotNull(result);
        assertTrue(result instanceof org.jdom2.Document);

        org.jdom2.Document doc = (org.jdom2.Document) result;
        assertEquals("root", doc.getRootElement().getName());

        org.jdom2.Element child = doc.getRootElement().getChild("child");
        assertNotNull(child);
        assertEquals("value", child.getText());
    }

    @Test
    void testParseXMLThrowsOnInvalidXML() throws Exception {
        String xml = "<root><child>value</root>";
        InputStream in = new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8));
        JDOMParser parser = new JDOMParser();

        assertThrows(org.apache.commons.jxpath.JXPathException.class, () -> {
            parser.parseXML(in);
        });
    }

    @Test
    void testParseXMLWithNamespaces() throws Exception {
        String xml = "<ns:root xmlns:ns='http://example.org/ns'><ns:child>text</ns:child></ns:root>";
        InputStream in = new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8));
        JDOMParser parser = new JDOMParser();

        Object result = parser.parseXML(in);
        assertNotNull(result);
        org.jdom2.Document doc = (org.jdom2.Document) result;

        assertEquals("root", doc.getRootElement().getName());
        assertEquals("http://example.org/ns", doc.getRootElement().getNamespaceURI());

        org.jdom2.Element child = doc.getRootElement().getChild("child", doc.getRootElement().getNamespace());
        assertNotNull(child);
        assertEquals("text", child.getText());
    }
}

