package org.apache.commons.jxpath;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.lang.reflect.Modifier;

import static org.junit.jupiter.api.Assertions.*;

public class NewInstanceTests {

    private String originalFactoryImplName;

    @BeforeEach
    void captureOriginalFactoryImplName() throws Exception {
        Field field = JXPathContextFactory.class.getDeclaredField("FACTORY_IMPL_NAME");
        field.setAccessible(true);
        originalFactoryImplName = (String) field.get(null);
    }

    @AfterEach
    void restoreOriginalFactoryImplName() throws Exception {
        Field field = JXPathContextFactory.class.getDeclaredField("FACTORY_IMPL_NAME");
        field.setAccessible(true);
        // Remove final modifier to allow restoration
        Field modifiersField = Field.class.getDeclaredField("modifiers");
        modifiersField.setAccessible(true);
        modifiersField.setInt(field, field.getModifiers() & ~Modifier.FINAL);
        field.set(null, originalFactoryImplName);
    }

    @Test
    void testNewInstanceReturnsNonNullFactory() {
        JXPathContextFactory instance = JXPathContextFactory.newInstance();
        assertNotNull(instance, "newInstance should return a non-null JXPathContextFactory instance");
        assertTrue(instance instanceof JXPathContextFactory, "Returned object should be instance of JXPathContextFactory");
    }

    @Test
    void testNewInstanceWithInvalidFactoryNameThrowsConfigurationError() {
        setFactoryImplName("org.example.nonexistent.FactoryNotExist222");
        assertThrows(JXPathContextFactoryConfigurationError.class, () -> {
            JXPathContextFactory.newInstance();
        }, "Expecting JXPathContextFactoryConfigurationError when factory class cannot be found");
    }

    @Test
    void testNewInstanceWithNoPublicNoArgCtorThrowsConfigurationError() {
        setFactoryImplName("org.apache.commons.jxpath.NewInstanceTests$FactoryNoPublicNoArgCtor");
        assertThrows(JXPathContextFactoryConfigurationError.class, () -> {
            JXPathContextFactory.newInstance();
        }, "Expecting JXPathContextFactoryConfigurationError when factory class has no public no-arg constructor");
    }

    private void setFactoryImplName(String name) {
        try {
            Field field = JXPathContextFactory.class.getDeclaredField("FACTORY_IMPL_NAME");
            field.setAccessible(true);

            // Remove final modifier to allow modification
            Field modifiersField = Field.class.getDeclaredField("modifiers");
            modifiersField.setAccessible(true);
            modifiersField.setInt(field, field.getModifiers() & ~Modifier.FINAL);

            field.set(null, name);
        } catch (Exception e) {
            throw new RuntimeException("Failed to set FACTORY_IMPL_NAME for test", e);
        }
    }

    // A test-specific factory class to trigger InstantiationException due to missing public no-arg ctor
    public static class FactoryNoPublicNoArgCtor {
        public FactoryNoPublicNoArgCtor(String s) {
        }
    }
}

