import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.lang.reflect.Method;

import org.apache.commons.jxpath.JXPathException;

public class LookupMethodTests {

    static class TargetExact {
        public String greet(String s) {
            return "hello " + s;
        }
    }

    static class TargetConversion {
        public int add(Number a, Number b) {
            return a.intValue() + b.intValue();
        }
    }

    static class TargetAmbiguity {
        public void doIt(Number n) { }
        public void doIt(Object o) { }
    }

    static class TargetNoMatch {
        public void something(int x) { }
    }

    @Test
    void testLookupMethodExactMatch() throws Exception {
        Method m = MethodLookupUtils.lookupMethod(TargetExact.class, "greet", new Object[]{"world"});
        assertNotNull(m, "Expected to find exact match method");
        assertEquals("greet", m.getName());
        assertEquals(1, m.getParameterCount());
        assertEquals(String.class, m.getParameterTypes()[0]);

        TargetExact t = new TargetExact();
        Object result = m.invoke(t, "world");
        assertEquals("hello world", result);
    }

    @Test
    void testLookupMethodConversionMatch() throws Exception {
        Method m = MethodLookupUtils.lookupMethod(TargetConversion.class, "add", new Object[]{Integer.valueOf(2), Integer.valueOf(3)});
        assertNotNull(m, "Expected to find a method via type conversion");
        assertEquals("add", m.getName());
        assertEquals(2, m.getParameterCount());

        TargetConversion t = new TargetConversion();
        Object result = m.invoke(t, Integer.valueOf(2), Integer.valueOf(3));
        assertEquals(5, result);
    }

    @Test
    void testLookupMethodAmbiguity() {
        assertThrows(JXPathException.class, () -> {
            MethodLookupUtils.lookupMethod(TargetAmbiguity.class, "doIt", new Object[]{Integer.valueOf(1)});
        });
    }

    @Test
    void testLookupMethodNoMatch() throws Exception {
        Method m = MethodLookupUtils.lookupMethod(TargetNoMatch.class, "notThere", new Object[]{1});
        assertNull(m);
    }

    @Test
    void testLookupMethodInvalidParametersReturnsNull() {
        assertNull(MethodLookupUtils.lookupMethod(TargetExact.class, "greet", null));
        assertNull(MethodLookupUtils.lookupMethod(TargetExact.class, "greet", new Object[]{}));
    }
}

package org.apache.commons.jxpath.util;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class LookupMethodTests {

    static class SampleWithOverloads {
        public void foo() { }
        public void foo(int x) { }
    }

    @Test
    void testNullParametersReturnsNull() {
        assertNull(MethodLookupUtils.lookupMethod(SampleWithOverloads.class, "foo", null), "Expected null when parameters are null");
        assertNull(MethodLookupUtils.lookupMethod(SampleWithOverloads.class, "foo", new Object[]{}), "Expected null when parameters are empty");
    }

    @Test
    void testNoSuchMethodReturnsNull() {
        assertNull(MethodLookupUtils.lookupMethod(SampleWithOverloads.class, "bar", new Object[]{1}), "Expected null when method does not exist");
    }

    @Test
    void testNullOrEmptyNameReturnsNull() {
        assertNull(MethodLookupUtils.lookupMethod(SampleWithOverloads.class, null, new Object[]{1}), "Expected null when method name is null");
        assertNull(MethodLookupUtils.lookupMethod(SampleWithOverloads.class, "", new Object[]{1}), "Expected null when method name is empty");
    }
}

